pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Tiempo de respuesta menor a 1000 ms", function () {
    pm.expect(pm.response.responseTime).to.be.below(1000);
});

pm.test("El cuerpo de la respuesta no está vacío", function () {
    pm.response.to.be.withBody;
    pm.expect(pm.response.text()).to.not.be.empty;
});

pm.test("Verificar encabezado Content-Type", function () {
    pm.response.to.have.header("Content-Type");
});

pm.test("El tamaño de la respuesta es válido", function () {
    pm.expect(pm.response.responseSize).to.be.above(0);
});
